      std::make_shared<VectorColumnIndexer>(output_index_path, index_field);
  bool reused_base_index = false;
  Status s;

  if (CanReuseFirstIndexer(source_indexers, index_field, filter)) {
    const auto &first_indexer = source_indexers.front();
    LOG_INFO(
        "Reusing first indexer as merge base. "
        "field[%s] src[%s] dst[%s] tail_indexers[%zu]",
        index_field.name().c_str(), first_indexer->index_file_path().c_str(),
        output_index_path.c_str(), source_indexers.size() - 1);
    if (FileHelper::CopyFile(first_indexer->index_file_path(),
                             output_index_path)) {
      // Open the copied file in-place (create_new=false).
      s = vector_indexer->open(vector_column_params::ReadOptions{true, false});
      CHECK_RETURN_STATUS(s);

      source_indexers.erase(source_indexers.begin());
      s = vector_indexer->merge(source_indexers, filter, merge_options);
      CHECK_RETURN_STATUS(s);
      reused_base_index = true;
    } else {
      LOG_WARN("Failed to copy %s to %s; falling back to full rebuild",
               first_indexer->index_file_path().c_str(),
               output_index_path.c_str());
    }
  }

  if (!reused_base_index) {
    s = vector_indexer->open(vector_column_params::ReadOptions{true, true});
    CHECK_RETURN_STATUS(s);

    s = vector_indexer->merge(source_indexers, filter, merge_options);
    CHECK_RETURN_STATUS(s);
  }

  s = vector_indexer->flush();
  CHECK_RETURN_STATUS(s);
  if (merged_indexer != nullptr) {
    *merged_indexer = vector_indexer;
  } else {
    s = vector_indexer->close();
    CHECK_RETURN_STATUS(s);
  }
  return Status::OK();
}

vector_column_params::MergeOptions merge_options;
if (concurrency == 0) {
  merge_options.pool = GlobalResource::Instance().optimize_thread_pool();
  merge_options.write_concurrency =
      static_cast<uint32_t>(merge_options.pool->count());
} else {
  merge_options.write_concurrency = concurrency;
}

int MixedStreamerReducer::reduce_with_builder(const IndexFilter &filter) {
  std::vector<MergedProviderIndexHolder::Source> sources;
  sources.reserve(streamers_.size());

  for (size_t i = 0; i < streamers_.size(); ++i) {
    MergedProviderIndexHolder::Source source;
    source.owner = streamers_[i];
    source.reformer = source_streamers_reformers_[i];
    source.quantizer = source_streamers_quantizers_[i];
    const auto &meta = streamers_[i]->meta();
    source.provider_meta = IndexQueryMeta{
        meta.meta_type(),
        meta.data_type(),
        meta.unit_size(),
        meta.dimension(),
        source.quantizer ? static_cast<uint32_t>(source.quantizer->type()) : 0,
        meta.extra_meta_size()};
    // Builders consume original vectors, not encoded records. Plain FP32
    // quantization is an identity transform; keep its zero-copy ordinal path.
    // Cosine normalization and FP16/INT8/INT4 storage must be decoded first.
    source.need_revert =
        source.quantizer
            ? source.quantizer->type() != turbo::QuantizeType::kFp32 ||
                  meta.extra_meta_size() != 0
            : source.reformer != nullptr;
    sources.emplace_back(std::move(source));
  }

  auto holder = std::make_shared<MergedProviderIndexHolder>(
      original_query_meta_, std::move(sources));
  int ret = holder->init(filter, stop_flag_);
  if (ret != 0) {
    LOG_ERROR("Failed to initialize merged provider holder, ret=%d", ret);
    return ret;
  }

  stats_.set_filtered_count(holder->filtered_count());
  merged_holder_ = holder;

  AILEGO_DEFER([&]() { holder->set_stop_flag(nullptr); });
  IndexHolder::Pointer target_holder = holder;
  // IVF and DiskAnn propagate source read failures during dump.
  // Other builders retain an owned multipass snapshot, as before, so their
  // dump paths never depend on a source provider or its deferred error state.
  if (target_builder_->name() != "IVFBuilder" &&
      target_builder_->name() != "DiskAnnBuilder") {
    switch (holder->data_type()) {
      case IndexMeta::DataType::DT_FP32:
        ret = MaterializeMergedInput<IndexMeta::DataType::DT_FP32, float>(
            holder, &target_holder);
        break;
      case IndexMeta::DataType::DT_FP16:
        ret = MaterializeMergedInput<IndexMeta::DataType::DT_FP16,
                                     ailego::Float16>(holder, &target_holder);
        break;
      case IndexMeta::DataType::DT_INT8:
        ret = MaterializeMergedInput<IndexMeta::DataType::DT_INT8, int8_t>(
            holder, &target_holder);
        break;
      default:
        ret = IndexError_Unsupported;
        break;
    }
    if (ret != 0) {
      return ret;
    }
  }
  return this->index_build(std::move(target_holder));
}

//! Retrieve thread count in pool
size_t count() const override {
  return pool_.count();
}

if (target_builder_converter_) {
  int ret = core::IndexConverter::TrainAndTransform(target_builder_converter_,
                                                    target_holder, threads);

virtual int train(IndexHolder::Pointer holder) {
  return this->train(nullptr, std::move(holder));
}

virtual int build(IndexHolder::Pointer holder) {
  return this->build(nullptr, std::move(holder));
}

int DiskAnnBuilder::train_quantized_data(IndexThreads::Pointer threads) {
  LOG_INFO("Starting Train: Chunk Num: %u", pq_chunk_num_);

  ailego::ElapsedTime timer;

  quantizer_ = IndexFactory::CreateQuantizer("PqInt8Quantizer");
  if (!quantizer_) {
    LOG_ERROR("Create PqInt8Quantizer failed");
    return IndexError_NoExist;
  }

  ailego::Params qp;
  qp.set("num_chunk", pq_chunk_num_);
  // The quantizer creates its own pool, so bound it by the caller's pool.
  const auto pq_thread_count = static_cast<uint32_t>(std::max<size_t>(
      1, std::min<size_t>(build_thread_count_, threads->count())));
  qp.set("thread_count", pq_thread_count);
  qp.set("use_zero_mean", false);
  int ret = quantizer_->init(build_meta_, qp);
  if (ret != 0) {
    LOG_ERROR("PqInt8Quantizer init failed, ret=%d", ret);
    return ret;
  }

  // Keep the legacy prefix and sample order without materializing a second
  // training holder. The quantizer copies only its selected training rows.
  IndexHolder::Pointer training_holder = std::make_shared<PrefixIndexHolder>(
      holder_, max_train_sample_count_, build_meta_);
  ret = quantizer_->train(std::move(training_holder));
  if (ret != 0) {
    LOG_ERROR("PqInt8Quantizer train failed, ret=%d", ret);
    return ret;
  }

  std::string &quantizer_meta_buffer = entity_.pq_quantizer_meta_buffer();
  ret = quantizer_->serialize(&quantizer_meta_buffer);
  if (ret != 0) {
    LOG_ERROR("PqInt8Quantizer serialize failed, ret=%d", ret);
    return ret;
  }

  size_t pq_time = timer.milli_seconds();
  LOG_INFO("Train Quantized Data Done, time: %zu ms", pq_time);

  (*entity_.mutable_pq_meta()).quantizer_meta_buffer_size =
      quantizer_meta_buffer.size();
  (*entity_.mutable_pq_meta()).chunk_num = pq_chunk_num_;

  return 0;
}

// The quantizer creates its own pool, so bound it by the caller's pool.
const auto pq_thread_count = static_cast<uint32_t>(std::max<size_t>(
    1, std::min<size_t>(build_thread_count_, threads->count())));
qp.set("thread_count", pq_thread_count);

if (build_thread_count_ > std::thread::hardware_concurrency()) {
  LOG_WARN("Build thread count [%s] greater than cpu cores %u",
           PARAM_DISKANN_BUILDER_THREAD_COUNT.c_str(),
           std::thread::hardware_concurrency());
}

for (size_t i = 0; i < pool_count; ++i) {
  task_group->submit(
      ailego::Closure::New([this, typed_data, num, stride, i, pool_count,
                            max_iters, &finished]() {
        for (uint32_t m = static_cast<uint32_t>(i); m < num_chunk_;
             m += static_cast<uint32_t>(pool_count)) {
          train_chunk<T>(typed_data, num, stride, m, max_iters);
          finished++;
        }
      }));
}
